files={'src/moment_component_audit.py': '"""Transactional 2^4 weight/state interventions; this is an audit, not a policy.\n\nFresh head means PEFT\'s original saved head initializer, not a new independent\ndraw. Inherited moments attached to reset weights are deliberate artificial\ncounterfactuals. They are not recommended optimizer states for deployment.\n"""\nimport copy\nimport hashlib\nimport inspect\nimport itertools\n\nimport torch\nimport torch.nn.functional as F\n\nfrom experiments.signal_scan import encode\nfrom experiments.day2_predictor_scan_rngsafe import capture_rng_state, restore_rng_state\nfrom src.component_intervention_audit import component_parameters\n\n\nFACTORS = (\'reset_lora_weights\', \'reset_head_weights\',\n           \'reset_lora_optimizer\', \'reset_head_optimizer\')\nCELLS = tuple(dict(zip(FACTORS, values)) for values in itertools.product((False, True), repeat=4))\n\n\ndef tensor_digest(values):\n    """Small receipt for exactly which weights/state each cell received."""\n    digest = hashlib.sha256()\n    for name, value in sorted(values.items()):\n        digest.update(name.encode())\n        if torch.is_tensor(value):\n            tensor = value.detach().cpu().contiguous()\n            digest.update(str((tensor.dtype, tuple(tensor.shape))).encode())\n            digest.update(tensor.numpy().tobytes())\n        else:\n            digest.update(repr(value).encode())\n    return digest.hexdigest()\n\n\ndef moment_trial(pool, source, support_texts, support_labels, query_texts,\n                 query_labels, cell, label_group=None):\n    if set(cell) != set(FACTORS) or any(type(v) is not bool for v in cell.values()):\n        raise ValueError(\'A cell must specify all four Boolean interventions\')\n    if not support_texts or not query_texts:\n        raise ValueError(\'Nonempty support and query are required\')\n    if len(support_texts) != len(support_labels) or len(query_texts) != len(query_labels):\n        raise ValueError(\'Text/label lengths differ\')\n    active = pool.model.active_adapter\n    rng = capture_rng_state()\n    existing = [(p, p.requires_grad, None if p.grad is None else p.grad.detach().clone())\n                for p in pool.model.parameters()]\n    modes = [(m, m.training) for m in pool.model.modules()]\n    source_params = component_parameters(pool.model, source)\n    if {kind for kind, _ in source_params.values()} != {\'head\', \'lora\'}:\n        raise RuntimeError(\'Audit requires a private classifier and LoRA package\')\n    inherited_optimizer = pool.states[source].optimizer\n    if type(inherited_optimizer) is not torch.optim.AdamW:\n        raise RuntimeError(\'This audit is defined for ordinary torch AdamW\')\n    if len(inherited_optimizer.param_groups) != 1:\n        raise RuntimeError(\'Multiple optimizer groups need an explicit matched port\')\n    temp, optimizer = \'__weight_moment_audit__\', None\n    if temp in pool.model.peft_config:\n        raise RuntimeError(\'A temporary audit adapter already exists\')\n    try:\n        pool.model.add_adapter(temp, pool.cfg)\n        pool.activate(temp)\n        targets = component_parameters(pool.model, temp)\n        if set(targets) != set(source_params):\n            raise RuntimeError(\'Source and candidate parameter structures differ\')\n        for key, (kind, target) in targets.items():\n            if kind != source_params[key][0]:\n                raise RuntimeError(\'Component kind changed\')\n            old = source_params[key][1]\n            if target.shape != old.shape or target.dtype != old.dtype:\n                raise RuntimeError(\'Source/candidate component shape or dtype differs\')\n            if not cell[f\'reset_{kind}_weights\']:\n                with torch.no_grad():\n                    target.copy_(source_params[key][1])\n        params = [p for _, p in targets.values()]\n        if {id(p) for p in params} != {id(p) for p in pool.model.parameters() if p.requires_grad}:\n            raise RuntimeError(\'Unexpected trainable parameters outside the private package\')\n        initial = {k: p.detach().clone() for k, (_, p) in targets.items()}\n        accepted = set(inspect.signature(torch.optim.AdamW).parameters) - {\'params\'}\n        # Read the actual group (which may differ from constructor defaults).\n        group = copy.deepcopy({k: v for k, v in inherited_optimizer.param_groups[0].items() if k != \'params\'})\n        extra = set(group) - accepted\n        if extra - {\'decoupled_weight_decay\', \'initial_lr\'} or group.get(\'decoupled_weight_decay\', True) is not True:\n            raise RuntimeError(f\'Unsupported AdamW group fields: {extra}\')\n        optimizer = torch.optim.AdamW(params, **{k: v for k, v in group.items() if k in accepted})\n        copied = {\'head\': 0, \'lora\': 0}\n        for key, (kind, target) in targets.items():\n            old = source_params[key][1]\n            if not cell[f\'reset_{kind}_optimizer\'] and old in inherited_optimizer.state:\n                for field in [\'exp_avg\',\'exp_avg_sq\',\'max_exp_avg_sq\']:\n                    value = inherited_optimizer.state[old].get(field)\n                    if value is not None and value.shape != target.shape:\n                        raise RuntimeError(\'Transported moment shape differs: \' + key + \':\' + field)\n                optimizer.state[target] = copy.deepcopy(inherited_optimizer.state[old])\n                copied[kind] += 1\n        receipts = {}\n        for kind in [\'head\', \'lora\']:\n            receipts[kind + \'_initial_weights_sha256\'] = tensor_digest(\n                {k: initial[k] for k, (which, _) in targets.items() if which == kind})\n            receipts[kind + \'_initial_optimizer_sha256\'] = tensor_digest(\n                {k + \':\' + field: value for k, (which, p) in targets.items() if which == kind\n                 for field, value in optimizer.state.get(p, {}).items()})\n            receipts[kind + \'_inherited_state_parameters\'] = copied[kind]\n        # Every cell receives the same initialization and support dropout draw.\n        # All initialization and training randomness is restored on exit.\n        restore_rng_state(rng)\n        sx, qx = encode(pool.tok, support_texts, pool.device), encode(pool.tok, query_texts, pool.device)\n        sy = torch.tensor(support_labels, device=pool.device)\n        qy = torch.tensor(query_labels, device=pool.device)\n        pool.model.eval()\n        with torch.no_grad():\n            before_logits = pool.model(**qx).logits\n            before = F.cross_entropy(before_logits, qy, reduction=\'none\')\n            before_mean = F.cross_entropy(before_logits, qy)\n            group = list(range(before_logits.shape[-1])) if label_group is None else list(label_group)\n            if len(set(group)) != len(group) or not set(query_labels + support_labels) <= set(group):\n                raise ValueError(\'Audit label group must uniquely include every batch label\')\n            if not group or min(group) < 0 or max(group) >= before_logits.shape[-1]:\n                raise ValueError(\'Audit label group lies outside the full output space\')\n            before_mass = before_logits.logsumexp(-1) - before_logits[:, group].logsumexp(-1)\n            before_conditional = before - before_mass\n        pool.model.train()\n        optimizer.zero_grad(set_to_none=True)\n        support_loss = pool.model(**sx, labels=sy).loss\n        support_loss.backward()\n        torch.nn.utils.clip_grad_norm_(params, 1.0)\n        optimizer.step()\n        pool.model.eval()\n        with torch.no_grad():\n            after_logits = pool.model(**qx).logits\n            after = F.cross_entropy(after_logits, qy, reduction=\'none\')\n            after_mean = F.cross_entropy(after_logits, qy)\n            after_mass = after_logits.logsumexp(-1) - after_logits[:, group].logsumexp(-1)\n            after_conditional = after - after_mass\n        if not torch.isfinite(before).all() or not torch.isfinite(after).all() or not torch.isfinite(support_loss):\n            raise RuntimeError(\'Nonfinite intervention loss\')\n        return {**cell, **receipts, \'query_before\': float(before_mean),\n                \'query_after\': float(after_mean), \'local_trainability\': float(before_mean - after_mean),\n                \'label_group\': group, \'group_mass_loss_before\': float(before_mass.mean()),\n                \'group_mass_loss_after\': float(after_mass.mean()),\n                \'within_group_loss_before\': float(before_conditional.mean()),\n                \'within_group_loss_after\': float(after_conditional.mean()),\n                \'query_before_each\': before.cpu().tolist(), \'query_after_each\': after.cpu().tolist(),\n                \'support_loss\': float(support_loss.detach()), \'support_n\': len(support_texts),\n                \'query_n\': len(query_texts), **{kind + \'_update_l2\': sum(float((p.detach() - initial[k]).square().sum())\n                    for k, (which, p) in targets.items() if which == kind) ** .5 for kind in [\'head\', \'lora\']}}\n    finally:\n        if optimizer is not None:\n            optimizer.zero_grad(set_to_none=True)\n        if temp in pool.model.peft_config:\n            pool.activate(active)\n            pool.model.delete_adapter(temp)\n        pool.activate(active)\n        for parameter, requires_grad, grad in existing:\n            parameter.requires_grad_(requires_grad)\n            parameter.grad = grad\n        for module, training in modes:\n            module.training = training\n        restore_rng_state(rng)\n\n\ndef crossfit_moments(pool, texts, labels, source, cells=CELLS, label_group=None):\n    """Each example is queried once in each cell, including odd-sized batches."""\n    if len(texts) < 2:\n        return []\n    if len(texts) != len(labels):\n        raise ValueError(\'Text/label lengths differ\')\n    rows = []\n    for fold, support, query in [(\'A\', list(range(0, len(texts), 2)), list(range(1, len(texts), 2))),\n                                 (\'B\', list(range(1, len(texts), 2)), list(range(0, len(texts), 2)))]:\n        for cell in cells:\n            result = moment_trial(pool, source, [texts[i] for i in support], [labels[i] for i in support],\n                                  [texts[i] for i in query], [labels[i] for i in query], cell, label_group=label_group)\n            rows.append({\'source_adapter\': source, \'fold\': fold, \'query_indices\': query, **result})\n    return rows\n', 'experiments/day15_moment_integrity.py': '"""Meaningful CPU/GPU checks for the four-factor causal audit."""\nimport argparse\nimport torch\nfrom transformers import DistilBertConfig, DistilBertForSequenceClassification\nfrom peft import LoraConfig, TaskType, get_peft_model\n\nfrom experiments.signal_scan import seed_all, encode\nfrom experiments.day3_action_utility_unit import nested_equal\nfrom experiments.day5_shared_head_integrity import Tokenizer, snapshot, check\nfrom src.adapter_pool_cau_v1 import CAUV1AdapterPool\nfrom src.component_intervention_audit import component_trial\nfrom src.moment_component_audit import CELLS, FACTORS, moment_trial, crossfit_moments\n\n\ndef main():\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\'--device\', choices=[\'cpu\', \'cuda\'], default=\'cpu\')\n    args = parser.parse_args()\n    torch.set_num_threads(2)\n    seed_all(2032)\n    device = torch.device(args.device)\n    model = DistilBertForSequenceClassification(DistilBertConfig(vocab_size=64, dim=32,\n        hidden_dim=64, n_heads=4, n_layers=2, num_labels=3,\n        dropout=.1, attention_dropout=.1, seq_classif_dropout=.1))\n    cfg = LoraConfig(task_type=TaskType.SEQ_CLS, r=2, lora_alpha=4, lora_dropout=0.,\n                     target_modules=[\'q_lin\', \'v_lin\'], bias=\'none\')\n    model = get_peft_model(model, cfg).to(device)\n    pool = CAUV1AdapterPool(model=model, tokenizer=Tokenizer(), lora_config=cfg, device=device,\n        lr=2e-4, memory_size=16, memory_probe=4, threshold=0., seed=2032)\n    texts, labels = [\'good item\', \'bad item\', \'new item\', \'old item\'], [0, 1, 2, 0]\n    for _ in range(3):\n        pool.train_step(\'default\', texts, labels)\n    pool.warmup_name = None\n    # Deliberately preserve stale gradients, mixed module modes and inactive state.\n    before = snapshot(pool)\n    trials = []\n    for cell in CELLS:\n        trials.append(moment_trial(pool, \'default\', texts, labels, texts, labels, cell))\n        check(str(tuple(cell.values())) + \' restores complete live state\', nested_equal(before, snapshot(pool)))\n    check(\'all 16 cells exist exactly once\', len({tuple(r[k] for k in FACTORS) for r in trials}) == 16)\n    for kind in [\'head\', \'lora\']:\n        for reset in [False, True]:\n            matching = [r for r in trials if r[f\'reset_{kind}_weights\'] == reset]\n            check(kind + f\' matched initializer {reset}\', len({r[kind + \'_initial_weights_sha256\'] for r in matching}) == 1)\n        check(kind + \' optimizer transport is independent of weights\',\n              len({r[kind + \'_initial_optimizer_sha256\'] for r in trials if not r[f\'reset_{kind}_optimizer\']}) == 1)\n        check(kind + \' empty optimizer state is empty in every cell\',\n              all(r[kind + \'_inherited_state_parameters\'] == 0 for r in trials if r[f\'reset_{kind}_optimizer\']))\n        check(kind + \' inherited state is present even with reset weights\',\n              all(r[kind + \'_inherited_state_parameters\'] > 0 for r in trials if not r[f\'reset_{kind}_optimizer\']))\n    for lora in [False, True]:\n        for head in [False, True]:\n            matching = [r for r in trials if r[\'reset_lora_weights\'] == lora and r[\'reset_head_weights\'] == head]\n            check(\'moments do not affect initial prediction\', len({r[\'query_before\'] for r in matching}) == 1)\n            variant = (\'fresh\' if lora else \'reuse\') + \'_lora_\' + (\'fresh\' if head else \'inherit\') + \'_head\'\n            old = component_trial(pool, \'default\', texts, labels, texts, labels, variant)\n            new = next(r for r in matching if r[\'reset_lora_optimizer\'] == lora and r[\'reset_head_optimizer\'] == head)\n            check(\'old coupled cell matches \' + variant, abs(old[\'query_after\'] - new[\'query_after\']) < 1e-7)\n    inherited = trials[0]\n    group_trial = moment_trial(pool,\'default\',texts,[0,1,1,0],texts,[0,1,1,0],CELLS[0],label_group=[0,1])\n    for phase in [\'before\',\'after\']:\n        check(\'full loss separates class-group mass and conditional loss \'+phase,\n              abs(group_trial[\'query_\'+phase]-group_trial[\'group_mass_loss_\'+phase]\n                  -group_trial[\'within_group_loss_\'+phase])<1e-6)\n    check(\'label-group measurement is non-invasive\',nested_equal(before,snapshot(pool)))\n    pool.train_step(\'default\', texts, labels)\n    model.eval()\n    with torch.no_grad():\n        actual = float(model(**encode(pool.tok, texts, device), labels=torch.tensor(labels, device=device)).loss)\n    check(\'fully inherited cell equals real optimizer update\', abs(actual - inherited[\'query_after\']) < 1e-7)\n    before = snapshot(pool)\n    records = crossfit_moments(pool, texts + [\'fifth item\'], labels + [1], \'default\')\n    for cell in CELLS:\n        matching = [r for r in records if all(r[k] == cell[k] for k in FACTORS)]\n        check(\'odd crossfit query partition\', sorted(i for r in matching for i in r[\'query_indices\']) == list(range(5)))\n    check(\'crossfit is non-invasive\', nested_equal(before, snapshot(pool)))\n    backward = crossfit_moments(pool, texts + [\'fifth item\'], labels + [1], \'default\', cells=tuple(reversed(CELLS)))\n    key = lambda r: (r[\'fold\'], tuple(r[k] for k in FACTORS))\n    check(\'cell order does not change losses or receipts\',\n          sorted(records, key=key) == sorted(backward, key=key))\n    check(\'reverse crossfit is non-invasive\', nested_equal(before, snapshot(pool)))\n    print(\'DAY15_WEIGHT_MOMENT_INTEGRITY_PASS\', args.device, flush=True)\n\n\nif __name__ == \'__main__\':\n    main()\n', 'experiments/day15_weight_moment_recurrence.py': '"""Four-factor observational audit on a verified fixed-memory trajectory.\n\nReuse the frozen trainer unchanged. The observer replaces only its optional\ncomponent measurements and must reproduce the unaudited reference state.\n"""\nimport argparse\nimport hashlib\nimport json\nfrom pathlib import Path\nimport sys\n\nimport numpy as np\nimport pandas as pd\nimport torch\nfrom safetensors.torch import load_file\n\nfrom experiments import day8_fixed_memory_recurrence as trainer\nfrom experiments.day3_action_utility_unit import nested_equal\nfrom src.moment_component_audit import crossfit_moments\n\n\ndef sha(path):\n    return hashlib.sha256(Path(path).read_bytes()).hexdigest()\n\n\ndef verify_replay(output, reference):\n    old = json.loads((reference / \'provenance.json\').read_text())\n    new = json.loads((output / \'provenance.json\').read_text())\n    if new[\'stream_sha256\'] != old[\'stream_sha256\']:\n        raise RuntimeError(\'Unpaired observer/reference data streams\')\n    left, right = [pd.read_csv(p / \'routing.csv\') for p in [reference, output]]\n    if len(left) != len(right) or len(right) != 80:\n        raise RuntimeError(\'Incomplete observer or reference trajectory\')\n    columns = [\'step\', \'adapter\', \'decision\', \'train_executed\', \'num_adapters\', \'replay_items\']\n    if not left[columns].equals(right[columns]):\n        raise RuntimeError(\'Observer changed the real action or memory trajectory\')\n    if not np.allclose(left.loss, right.loss, atol=1e-6, rtol=0, equal_nan=True):\n        raise RuntimeError(\'Observer changed real training loss\')\n    a, b = [torch.load(p / \'checkpoint/learner_state.pt\', map_location=\'cpu\', weights_only=False)\n            for p in [reference, output]]\n    if not nested_equal(a, b):\n        raise RuntimeError(\'Observer final learner state is not bitwise identical\')\n    paths = sorted((reference / \'checkpoint/adapters\').rglob(\'*.safetensors\'))\n    if not paths:\n        raise RuntimeError(\'Reference has no saved adapter tensors\')\n    for path in paths:\n        other = output / path.relative_to(reference)\n        if not other.exists() or not nested_equal(load_file(str(path)), load_file(str(other))):\n            raise RuntimeError(\'Observer changed saved adapter weights: \' + str(path))\n    return {\'status\': \'passed\', \'reference\': str(reference), \'reference_learner_sha256\':\n            sha(reference / \'checkpoint/learner_state.pt\'), \'output_learner_sha256\':\n            sha(output / \'checkpoint/learner_state.pt\'), \'bitwise_learner_state_equal\': True,\n            \'bitwise_adapter_tensors_equal\': True, \'adapter_files_checked\': len(paths),\n            \'training_loss_absolute_tolerance\': 1e-6,\n            \'maximum_training_loss_difference\': float(np.nanmax(np.abs(left.loss - right.loss))),\n            \'stream_sha256\': new[\'stream_sha256\']}\n\n\ndef main():\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\'--regime\', choices=[\'banking\', \'amazon\'], required=True)\n    parser.add_argument(\'--seed\', type=int, required=True)\n    parser.add_argument(\'--order\', choices=[\'canonical\', \'b_first\'], required=True)\n    parser.add_argument(\'--output\', required=True)\n    parser.add_argument(\'--deadline-utc\', required=True)\n    args = parser.parse_args()\n    reference = Path(f\'results/day8_{args.regime}_private_cau_seed{args.seed}_{args.order}_fixed512\')\n    if json.loads((reference / \'summary.json\').read_text())[\'status\'] != \'completed\':\n        raise RuntimeError(\'A complete unaudited reference is required\')\n    spec = Path(\'notes/day15_weight_moment_spec.md\')\n    implementation = [\'src/moment_component_audit.py\', \'experiments/day15_weight_moment_recurrence.py\',\n                      \'experiments/day8_fixed_memory_recurrence.py\']\n    receipt = {\'audit_spec_sha256\': sha(spec), \'audit_implementation_sha256\': {p: sha(p) for p in implementation},\n               \'audit_kind\': \'observational_four_factor_weight_optimizer_state\', \'reference\': str(reference),\n               \'all_mature_batches\': True, \'official_test_used\': False}\n    print(\'DAY15_FROZEN_OBSERVER\', json.dumps(receipt, sort_keys=True), flush=True)\n    def observer(pool, texts, labels, source):\n        # Evaluator-only label grouping decomposes already computed losses.\n        # It is never supplied to allocation, training, or deployment routing.\n        if args.regime == \'banking\':\n            index = labels[0] // 11\n            group = list(range(11*index, 11*(index+1)))\n        else:\n            group = [0, 1]\n        return crossfit_moments(pool, texts, labels, source, label_group=group)\n    trainer.crossfit_components = observer\n    sys.argv = [\'day8_fixed_memory_recurrence\', \'--regime\', args.regime, \'--architecture\', \'private\',\n                \'--policy\', \'cau\', \'--seed\', str(args.seed), \'--order\', args.order, \'--component-audit\',\n                \'--output\', args.output, \'--deadline-utc\', args.deadline_utc]\n    trainer.main()\n    output = Path(args.output)\n    provenance = json.loads((output / \'provenance.json\').read_text())\n    provenance.update(receipt)\n    (output / \'provenance.json\').write_text(json.dumps(provenance, indent=2))\n    if json.loads((output / \'summary.json\').read_text())[\'status\'] != \'completed\':\n        raise RuntimeError(\'Incomplete audit preserved; no replay/causal claim permitted\')\n    # Failed checks leave every measurement and attempt intact for inspection.\n    verification = verify_replay(output, reference)\n    (output / \'observer_verification.json\').write_text(json.dumps(verification, indent=2))\n    print(\'DAY15_OBSERVER_REPLAY_PASS\', args.regime, args.seed, args.order, flush=True)\n\n\nif __name__ == \'__main__\':\n    main()\n', 'experiments/day15_moment_report.py': '"""All conditional and marginal contrasts, clustered by training seed."""\nimport ast\nimport itertools\nimport json\nfrom pathlib import Path\n\nimport numpy as np\nimport pandas as pd\nfrom scipy.stats import t\n\nfrom src.moment_component_audit import FACTORS\nfrom experiments.day5_report import markdown_table\n\n\ndef interval(values):\n    a = np.asarray(values, dtype=float)\n    mean = float(a.mean())\n    width = float(t.ppf(.975, len(a)-1) * a.std(ddof=1) / len(a)**.5) if len(a)>1 else float(\'nan\')\n    return {\'n_seeds\': len(a), \'mean\': mean, \'ci_low\': mean-width, \'ci_high\': mean+width}\n\n\ndef main():\n    observations, coverage, incomplete = [], [], []\n    for folder in sorted(Path(\'results\').glob(\'day15_*_weight_moments\')):\n        verification = folder / \'observer_verification.json\'\n        if not verification.exists():\n            incomplete.append(folder.name)\n            continue\n        if json.loads(verification.read_text())[\'status\'] != \'passed\':\n            raise RuntimeError(\'Invalid observer receipt \' + str(folder))\n        provenance = json.loads((folder / \'provenance.json\').read_text())\n        args = provenance[\'args\']\n        if not args[\'component_audit\'] or args[\'architecture\'] != \'private\' or args[\'policy\'] != \'cau\':\n            raise RuntimeError(\'Incorrect audit information condition\')\n        data = pd.read_csv(folder / \'component_trials.csv\')\n        for factor in FACTORS:\n            if data[factor].dtype != bool:\n                raise RuntimeError(\'Factor coding must be Boolean\')\n        route = pd.read_csv(folder / \'routing.csv\')\n        if data.empty or len(route) != 80:\n            raise RuntimeError(\'Empty or incomplete audit\')\n        # Per-example data provide coverage receipts, not independent replicates.\n        for step, batch in data.groupby(\'step\'):\n            if len(batch) != 32 or len(set(batch.source_adapter)) != 1:\n                raise RuntimeError(\'Missing factorial cell or inconsistent source\')\n            for key, cell in batch.groupby(list(FACTORS)):\n                if set(cell.fold) != {\'A\', \'B\'} or len(cell) != 2:\n                    raise RuntimeError(\'Missing complementary folds\')\n                indices = [i for value in cell.query_indices for i in ast.literal_eval(value)]\n                n = int(cell.query_n.sum())\n                if sorted(indices) != list(range(n)):\n                    raise RuntimeError(\'Crossfit does not query each batch example once\')\n                for row in cell.itertuples():\n                    before, after = [ast.literal_eval(getattr(row, field))\n                                     for field in [\'query_before_each\', \'query_after_each\']]\n                    if len(before) != row.query_n or len(after) != row.query_n:\n                        raise RuntimeError(\'Per-example receipt has incorrect count\')\n                    if not np.isfinite(before + after).all():\n                        raise RuntimeError(\'Nonfinite per-example loss\')\n        weighted = []\n        for key, part in data.groupby([\'step\', *FACTORS]):\n            row = dict(zip([\'step\', *FACTORS], key))\n            row.update({metric: np.average(part[metric], weights=part.query_n)\n                        for metric in [\'query_before\', \'query_after\', \'local_trainability\',\n                                       \'group_mass_loss_before\',\'group_mass_loss_after\',\n                                       \'within_group_loss_before\',\'within_group_loss_after\']})\n            weighted.append(row)\n        weighted = pd.DataFrame(weighted)\n        for step, part in weighted.groupby(\'step\'):\n            cells = {tuple(row[f] for f in FACTORS): row for _, row in part.iterrows()}\n            if len(cells) != 16:\n                raise RuntimeError(\'Missing factorial cell\')\n            metadata = {\'run\': folder.name, \'regime\': args[\'regime\'], \'seed\': args[\'seed\'],\n                        \'order\': args[\'order\'], \'step\': step}\n            for j, factor in enumerate(FACTORS):\n                other = [i for i in range(4) if i != j]\n                for condition in itertools.product((False, True), repeat=3):\n                    a = [False]*4\n                    for i, value in zip(other, condition):\n                        a[i] = value\n                    b = a.copy()\n                    b[j] = True\n                    a, b = cells[tuple(a)], cells[tuple(b)]\n                    initial = a.query_before - b.query_before\n                    local = b.local_trainability - a.local_trainability\n                    effect = a.query_after - b.query_after\n                    if abs(effect-initial-local) > 1e-6:\n                        raise RuntimeError(\'Effect decomposition failed\')\n                    extra = {\'initial_group_mass_decrease\': a.group_mass_loss_before-b.group_mass_loss_before,\n                             \'initial_within_group_decrease\': a.within_group_loss_before-b.within_group_loss_before,\n                             \'post_group_mass_decrease\': a.group_mass_loss_after-b.group_mass_loss_after,\n                             \'post_within_group_decrease\': a.within_group_loss_after-b.within_group_loss_after}\n                    if (abs(initial-extra[\'initial_group_mass_decrease\']-extra[\'initial_within_group_decrease\']) > 1e-5\n                        or abs(effect-extra[\'post_group_mass_decrease\']-extra[\'post_within_group_decrease\']) > 1e-5):\n                        raise RuntimeError(\'Label-mass decomposition failed\')\n                    observations.append({**metadata, \'kind\': \'conditional\', \'factor\': factor,\n                        \'condition\': json.dumps({FACTORS[i]: v for i, v in zip(other, condition)}, sort_keys=True),\n                        \'post_update_loss_decrease\': effect, \'initial_loss_decrease\': initial,\n                        \'local_improvement_increase\': local, **extra})\n            for j, k in itertools.combinations(range(4), 2):\n                other = [i for i in range(4) if i not in [j, k]]\n                values = []\n                for condition in itertools.product((False, True), repeat=2):\n                    base = [False]*4\n                    for i, value in zip(other, condition):\n                        base[i] = value\n                    terms = {}\n                    for x, y in itertools.product((False, True), repeat=2):\n                        key = base.copy(); key[j], key[k] = x, y\n                        terms[x,y] = cells[tuple(key)]\n                    values.append({name: terms[True,False][metric]+terms[False,True][metric]\n                                  -terms[True,True][metric]-terms[False,False][metric]\n                        for name, metric in [(\'post_update_loss_decrease\',\'query_after\'),\n                                             (\'initial_loss_decrease\',\'query_before\'),\n                                             (\'initial_group_mass_decrease\',\'group_mass_loss_before\'),\n                                             (\'initial_within_group_decrease\',\'within_group_loss_before\'),\n                                             (\'post_group_mass_decrease\',\'group_mass_loss_after\'),\n                                             (\'post_within_group_decrease\',\'within_group_loss_after\')]})\n                    values[-1][\'local_improvement_increase\'] = (terms[True,True].local_trainability\n                        +terms[False,False].local_trainability-terms[True,False].local_trainability\n                        -terms[False,True].local_trainability)\n                averaged = {name: np.mean([v[name] for v in values]) for name in values[0]}\n                if abs(averaged[\'post_update_loss_decrease\']-averaged[\'initial_loss_decrease\']\n                       -averaged[\'local_improvement_increase\']) > 1e-6:\n                    raise RuntimeError(\'Interaction decomposition failed\')\n                observations.append({**metadata, \'kind\':\'interaction\', \'factor\': FACTORS[j]+\' x \'+FACTORS[k],\n                                     \'condition\':\'marginal_over_other_factors\', **averaged})\n        coverage.append({\'run\': folder.name, \'regime\': args[\'regime\'], \'seed\': args[\'seed\'],\n                         \'order\': args[\'order\'], \'mature_batches\': data.step.nunique(), \'raw_cell_fold_rows\': len(data)})\n    report = [\'# Separate weight and AdamW-state audit\', \'\',\n        \'Development-stage matched interventions. Positive contrasts mean lower post-update query loss, \'\n        \'lower initial query loss, or more local improvement when resetting the named factor. \'\n        \'All conditional cells and interactions are retained. Intervals are descriptive and are not \'\n        \'multiplicity-adjusted hypothesis tests.\', \'\', f\'Verified trajectories: {len(coverage)}/20. \'\n        f\'Incomplete or unverified attempts: {incomplete}.\', \'\']\n    if observations:\n        frame = pd.DataFrame(observations)\n        metrics = [\'post_update_loss_decrease\',\'initial_loss_decrease\',\'local_improvement_increase\',\n                   \'initial_group_mass_decrease\',\'initial_within_group_decrease\',\n                   \'post_group_mass_decrease\',\'post_within_group_decrease\']\n        group = [\'run\',\'regime\',\'seed\',\'order\',\'kind\',\'factor\',\'condition\']\n        trajectory = frame.groupby(group, as_index=False)[metrics].mean()\n        marginal = trajectory[trajectory.kind==\'conditional\'].groupby(\n            [\'run\',\'regime\',\'seed\',\'order\',\'factor\'], as_index=False)[metrics].mean()\n        marginal[\'kind\'], marginal[\'condition\'] = \'marginal\', \'average_over_all_other_factors\'\n        trajectory = pd.concat([trajectory,marginal], ignore_index=True)\n        frame.to_csv(\'results/day15_batch_contrasts.csv\',index=False)\n        trajectory.to_csv(\'results/day15_trajectory_contrasts.csv\',index=False)\n        pd.DataFrame(coverage).to_csv(\'results/day15_coverage.csv\',index=False)\n        summaries, seed_rows = [], []\n        for key, part in trajectory.groupby([\'regime\',\'kind\',\'factor\',\'condition\']):\n            paired = part.groupby(\'seed\').filter(lambda p: len(p)==2 and set(p.order)=={\'canonical\',\'b_first\'})\n            for seed, values in paired.groupby(\'seed\'):\n                seed_rows.append(dict(zip([\'regime\',\'kind\',\'factor\',\'condition\'],key))|\n                                 {\'seed\':seed}|{m: values[m].mean() for m in metrics})\n            for metric in metrics:\n                values = paired.groupby(\'seed\')[metric].mean()\n                if len(values):\n                    summaries.append(dict(zip([\'regime\',\'kind\',\'factor\',\'condition\'],key))|\n                                     {\'metric\':metric}|interval(values))\n        summary = pd.DataFrame(summaries, columns=[\'regime\',\'kind\',\'factor\',\'condition\',\'metric\',\n                                                  \'n_seeds\',\'mean\',\'ci_low\',\'ci_high\'])\n        pd.DataFrame(seed_rows).to_csv(\'results/day15_seed_contrasts.csv\',index=False)\n        summary.to_csv(\'results/day15_seed_intervals.csv\',index=False)\n        report += [\'## All marginal effects\', \'\', markdown_table(summary[summary.kind==\'marginal\']), \'\',\n                   \'## All conditional post-update effects\', \'\', markdown_table(summary[\n                       (summary.kind==\'conditional\')&(summary.metric==\'post_update_loss_decrease\')]), \'\',\n                   \'## All marginal two-factor interactions\', \'\', markdown_table(summary[summary.kind==\'interaction\']), \'\']\n    report += [\'## Interpretation limits\', \'\',\n        \'The probe source is the actual active package, not the best feasible reuse selected retrospectively. \'\n        \'This is one-step causal attribution of that probe, not a closed-loop effectiveness study or proof \'\n        \'of future plasticity. Resetting a classifier can be a legitimate prediction objective. \'\n        \'Five training seeds and fixed development examples do not establish population-level generalization. \'\n        \'Broader architectures, source-faithful comparators and stronger natural same-label regimes remain open.\']\n    Path(\'notes/day15_weight_moment_results.md\').write_text(\'\\n\'.join(report)+\'\\n\')\n    print(\'DAY15_REPORT_SAVED\', len(coverage), \'verified trajectories\', flush=True)\n\n\nif __name__==\'__main__\':\n    main()\n', 'experiments/day15_report_integrity.py': '"""Check known factor/interaction effects and partial-pair handling on synthetic data."""\nimport importlib\nimport itertools\nimport json\nimport os\nfrom pathlib import Path\nimport tempfile\n\nimport numpy as np\nimport pandas as pd\n\nfrom src.moment_component_audit import FACTORS\nfrom experiments import day15_moment_report as report\n\n\ndef main():\n    original = Path.cwd()\n    with tempfile.TemporaryDirectory(prefix=\'day15_synthetic_\',dir=original.parent) as temporary:\n        os.chdir(temporary)\n        try:\n            Path(\'notes\').mkdir();Path(\'results\').mkdir()\n            created=[]\n            for seed in range(2027,2032):\n                for order in [\'canonical\',\'b_first\']:\n                    for regime in [\'banking\',\'amazon\']:\n                        folder=Path(\'results\')/f\'day15_{regime}_{seed}_{order}_weight_moments\'\n                        folder.mkdir();created.append(folder)\n                        (folder/\'observer_verification.json\').write_text(json.dumps({\'status\':\'passed\'}))\n                        (folder/\'provenance.json\').write_text(json.dumps({\'args\':{\n                            \'seed\':seed,\'order\':order,\'regime\':regime,\'component_audit\':True,\n                            \'architecture\':\'private\',\'policy\':\'cau\'}}))\n                        pd.DataFrame({\'step\':range(1,81)}).to_csv(folder/\'routing.csv\',index=False)\n                        rows=[]\n                        for cell in itertools.product([False,True],repeat=4):\n                            initial=10-sum((i+1)*v for i,v in enumerate(cell))*.1\n                            gain=.02*sum(cell)+.08*cell[0]*cell[1]\n                            for fold,indices in [(\'A\',[1]),(\'B\',[0,2])]:\n                                rows.append(dict(zip(FACTORS,cell))|{\'step\':7,\'source_adapter\':\'default\',\n                                    \'fold\':fold,\'query_n\':len(indices),\'query_indices\':str(indices),\n                                    \'query_before\':initial,\'query_after\':initial-gain,\'local_trainability\':gain,\n                                    \'group_mass_loss_before\':.3*initial,\'within_group_loss_before\':.7*initial,\n                                    \'group_mass_loss_after\':.3*(initial-gain),\'within_group_loss_after\':.7*(initial-gain),\n                                    \'query_before_each\':str([initial]*len(indices)),\n                                    \'query_after_each\':str([initial-gain]*len(indices))})\n                        pd.DataFrame(rows).to_csv(folder/\'component_trials.csv\',index=False)\n            report.main();data=pd.read_csv(\'results/day15_seed_intervals.csv\')\n            assert set(data.n_seeds)=={5}\n            for factor,expected in zip(FACTORS,[.16,.26,.32,.42]):\n                values=data[(data.kind==\'marginal\')&(data.factor==factor)&\n                            (data.metric==\'post_update_loss_decrease\')]\n                assert np.allclose(values[\'mean\'],expected,atol=1e-12),factor\n            values=data[(data.kind==\'interaction\')&(data.factor==FACTORS[0]+\' x \'+FACTORS[1])&\n                        (data.metric==\'post_update_loss_decrease\')]\n            assert np.allclose(values[\'mean\'],.08,atol=1e-12)\n            mass=data[data.metric==\'post_group_mass_decrease\'].set_index([\'regime\',\'kind\',\'factor\',\'condition\'])[\'mean\']\n            full=data[data.metric==\'post_update_loss_decrease\'].set_index([\'regime\',\'kind\',\'factor\',\'condition\'])[\'mean\']\n            assert np.allclose(mass,.3*full,atol=1e-12),\'Known label-mass contributions must recover analytically\'\n            # Hide all but one synthetic trajectory without deleting any evidence.\n            for folder in created[1:]: folder.rename(folder.with_name(\'hidden_\'+folder.name))\n            report.main();partial=pd.read_csv(\'results/day15_seed_intervals.csv\')\n            assert partial.empty,\'An unpaired order must not form an independent seed cluster\'\n            print(\'DAY15_ANALYTIC_REPORT_INTEGRITY_PASS\',len(data),\'balanced intervals; unpaired order excluded\',flush=True)\n        finally:\n            os.chdir(original)\n\n\nif __name__==\'__main__\':\n    main()\n', 'experiments/day16_bert_allocation.py': '"""Cross-architecture allocation diagnostic using the frozen Day-8 trainer."""\nimport argparse\nimport hashlib\nimport json\nimport os\nfrom pathlib import Path\nimport sys\n\nimport numpy as np\nimport pandas as pd\nfrom peft import LoraConfig\nfrom transformers import AutoTokenizer, AutoModelForSequenceClassification\n\nfrom experiments import day8_fixed_memory_recurrence as trainer\n\n\nMODEL = \'google-bert/bert-base-uncased\'\n\n\nclass TokenizerFactory:\n    @staticmethod\n    def from_pretrained(_original, **kwargs):\n        return AutoTokenizer.from_pretrained(MODEL, **kwargs)\n\n\nclass ModelFactory:\n    @staticmethod\n    def from_pretrained(_original, **kwargs):\n        return AutoModelForSequenceClassification.from_pretrained(MODEL, **kwargs)\n\n\ndef bert_lora(**kwargs):\n    if kwargs[\'target_modules\'] != [\'q_lin\',\'v_lin\']:\n        raise RuntimeError(\'Unexpected reference LoRA targets\')\n    kwargs[\'target_modules\'] = [\'query\',\'value\']\n    return LoraConfig(**kwargs)\n\n\ndef main():\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\'--architecture\', choices=[\'private\',\'head_only\'], required=True)\n    parser.add_argument(\'--seed\',type=int,required=True)\n    parser.add_argument(\'--order\',choices=[\'canonical\',\'b_first\'],required=True)\n    parser.add_argument(\'--output\',required=True)\n    parser.add_argument(\'--deadline-utc\',required=True)\n    args=parser.parse_args()\n    pin=json.loads(Path(\'notes/day16_bert_backbone_pin.json\').read_text())\n    if pin[\'model_id\'] != MODEL or len(pin[\'revision\']) != 40:\n        raise RuntimeError(\'Missing explicit BERT snapshot pin\')\n    os.environ[\'MITOSIS_MODEL_REVISION\']=pin[\'revision\']\n    spec=Path(\'notes/day16_bert_allocation_spec.md\')\n    receipt={\'model_id\':MODEL,\'backbone_manifest_sha256\':hashlib.sha256(\n        Path(\'notes/day16_bert_backbone_pin.json\').read_bytes()).hexdigest(),\n        \'diagnostic_spec_sha256\':hashlib.sha256(spec.read_bytes()).hexdigest(),\n        \'diagnostic_implementation_sha256\':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),\n        \'architecture_scope\':\'BERT classifier-only output layer; frozen pooler\',\n        \'lora_targets\':[\'query\',\'value\'],\'official_test_used\':False}\n    print(\'DAY16_FROZEN_DIAGNOSTIC\',json.dumps(receipt,sort_keys=True),flush=True)\n    trainer.AutoTokenizer=TokenizerFactory\n    trainer.AutoModelForSequenceClassification=ModelFactory\n    trainer.LoraConfig=bert_lora\n    sys.argv=[\'day8_fixed_memory_recurrence\',\'--regime\',\'banking\',\'--architecture\',args.architecture,\n        \'--policy\',\'cau\',\'--seed\',str(args.seed),\'--order\',args.order,\'--output\',args.output,\n        \'--deadline-utc\',args.deadline_utc]\n    trainer.main()\n    folder=Path(args.output)\n    provenance=json.loads((folder/\'provenance.json\').read_text());provenance.update(receipt)\n    (folder/\'provenance.json\').write_text(json.dumps(provenance,indent=2))\n    summary=json.loads((folder/\'summary.json\').read_text())\n    routing=pd.read_csv(folder/\'routing.csv\')\n    if summary[\'status\']!=\'completed\' or len(routing)!=80:\n        raise RuntimeError(\'Incomplete architecture diagnostic preserved\')\n    if routing.replay_items.max()>512 or routing.num_adapters.max()>8:\n        raise RuntimeError(\'Architecture diagnostic resource bound violated\')\n    if not np.isfinite(routing.loc[routing.train_executed,\'loss\']).all():\n        raise RuntimeError(\'Nonfinite training losses\')\n    reference=Path(f\'results/day8_banking_{args.architecture}_cau_seed{args.seed}_{args.order}_fixed512\')\n    rp=json.loads((reference/\'provenance.json\').read_text())\n    if provenance[\'stream_sha256\']!=rp[\'stream_sha256\']:\n        raise RuntimeError(\'BERT and DistilBERT streams differ\')\n    print(\'DAY16_BERT_DIAGNOSTIC_PASS\',args.architecture,args.seed,args.order,flush=True)\n\n\nif __name__==\'__main__\':\n    main()\n', 'experiments/day16_bert_integrity.py': '"""Architecture-port checks on tiny local BERT, without downloaded research data."""\nimport argparse\nimport torch\nfrom transformers import BertConfig, BertForSequenceClassification\nfrom peft import LoraConfig, TaskType, get_peft_model\n\nfrom experiments.signal_scan import seed_all, encode\nfrom experiments.day3_action_utility_unit import nested_equal\nfrom experiments.day5_shared_head_integrity import Tokenizer, snapshot, check\nfrom src.adapter_pool_fixed_memory import FixedMemoryCAUV1AdapterPool, FixedMemoryHeadOnlyCAUV1AdapterPool\nfrom src.component_intervention_audit import component_parameters, component_trial\n\n\ndef main():\n    parser=argparse.ArgumentParser();parser.add_argument(\'--device\',choices=[\'cpu\',\'cuda\'],default=\'cpu\')\n    args=parser.parse_args();device=torch.device(args.device);torch.set_num_threads(2)\n    for architecture,kind in [(\'private\',FixedMemoryCAUV1AdapterPool),(\'head_only\',FixedMemoryHeadOnlyCAUV1AdapterPool)]:\n        seed_all(2032)\n        base=BertForSequenceClassification(BertConfig(vocab_size=64,hidden_size=32,\n            intermediate_size=64,num_attention_heads=4,num_hidden_layers=2,num_labels=3,\n            hidden_dropout_prob=.1,attention_probs_dropout_prob=.1,classifier_dropout=.1))\n        cfg=LoraConfig(task_type=TaskType.SEQ_CLS,r=2,lora_alpha=4,lora_dropout=0.,\n            target_modules=[\'query\',\'value\'],bias=\'none\')\n        model=get_peft_model(base,cfg).to(device)\n        pool=kind(model=model,tokenizer=Tokenizer(),lora_config=cfg,device=device,lr=2e-4,\n            memory_size=32,total_memory_budget=32,memory_probe=4,max_adapters=8,threshold=0.,seed=2032)\n        texts,labels=[\'good item\',\'bad item\',\'new item\',\'old item\'],[0,1,2,0]\n        for _ in range(3): pool.train_step(\'default\',texts,labels)\n        pool.warmup_name=None\n        parameters=component_parameters(model,\'default\')\n        check(architecture+\' single private linear classifier\',sum(k==\'head\' for k,p in parameters.values())==2)\n        check(architecture+\' frozen pooler\',all(not p.requires_grad for n,p in model.named_parameters() if \'.pooler.\' in n))\n        before=snapshot(pool)\n        pool.crossfit_action_utility(texts,labels,\'default\')\n        check(architecture+\' exact crossfit state restoration\',nested_equal(before,snapshot(pool)))\n        trial=pool.shadow_reuse(\'default\',texts,labels,texts,labels,\'default\')\n        check(architecture+\' inherited intervention restoration\',nested_equal(before,snapshot(pool)))\n        pool.train_step(\'default\',texts,labels);model.eval()\n        with torch.no_grad():actual=float(model(**encode(pool.tok,texts,device),labels=torch.tensor(labels,device=device)).loss)\n        check(architecture+\' intervention equals actual update\',abs(actual-trial[\'query_after\'])<1e-7)\n        new=pool.spawn();pool.train_step(new,texts,labels);pool.assert_memory_budget()\n        check(architecture+\' multi-package allocation budget\',sum(s.memory.capacity for s in pool.states.values())<=32)\n        if architecture==\'head_only\':\n            check(\'head-only LoRA is zero and frozen\',all(not p.requires_grad for n,p in model.named_parameters() if \'lora_\' in n)\n                and all(torch.count_nonzero(p)==0 for n,p in model.named_parameters() if \'lora_B\' in n))\n        else:\n            before=snapshot(pool)\n            component_trial(pool,new,texts,labels,texts,labels,\'reuse_lora_inherit_head\')\n            check(\'BERT component cloning is non-invasive\',nested_equal(before,snapshot(pool)))\n    print(\'DAY16_BERT_INTEGRITY_PASS\',args.device,flush=True)\n\n\nif __name__==\'__main__\':main()\n', 'experiments/day16_bert_report.py': '"""All BERT allocation pairs and deployment rules, without winner selection."""\nimport json\nfrom pathlib import Path\nimport pandas as pd\nfrom experiments.day5_report import markdown_table\nfrom experiments.day6_diagnostic_report import interval\n\n\ndef main():\n    rows, pairs, partial = [], [], []\n    for seed in range(2027,2032):\n        for order in [\'canonical\',\'b_first\']:\n            routes={}\n            for architecture in [\'private\',\'head_only\']:\n                folder=Path(f\'results/day16_banking_{architecture}_seed{seed}_{order}_bert\')\n                if not folder.exists():continue\n                if not (folder/\'summary.json\').exists() or json.loads((folder/\'summary.json\').read_text())[\'status\']!=\'completed\':\n                    partial.append(folder.name);continue\n                provenance=json.loads((folder/\'provenance.json\').read_text())\n                summary=json.loads((folder/\'summary.json\').read_text())\n                route=pd.read_csv(folder/\'routing.csv\');routes[architecture]=(route,provenance)\n                metrics=pd.read_csv(folder/\'label_free_eval.csv\');metrics=metrics[metrics.step==80]\n                if len(route)!=80 or len(metrics)!=9:raise RuntimeError(\'Incomplete BERT evidence\')\n                reference=Path(f\'results/day8_banking_{architecture}_cau_seed{seed}_{order}_fixed512\')\n                rp=json.loads((reference/\'provenance.json\').read_text())\n                if provenance[\'stream_sha256\']!=rp[\'stream_sha256\']:raise RuntimeError(\'Unpaired cross-backbone stream\')\n                old=pd.read_csv(reference/\'label_free_eval.csv\');old=old[old.step==80]\n                for rule,part in metrics.groupby(\'rule\'):\n                    rows.append({\'seed\':seed,\'order\':order,\'architecture\':architecture,\'rule\':rule,\n                        \'bert_macro_accuracy\':part.accuracy.mean(),\n                        \'distilbert_macro_accuracy\':old[old.rule==rule].accuracy.mean(),\n                        \'bert_minus_distilbert\':part.accuracy.mean()-old[old.rule==rule].accuracy.mean(),\n                        \'updates\':summary[\'learning_updates\'],\'adapters\':len(summary[\'final_adapters\']),\n                        \'adaptation_parameters\':summary[\'resources\'][\'private_head_parameters\']+summary[\'resources\'][\'lora_parameters\'],\n                        \'maximum_training_texts\':int(route.replay_items.max())})\n            if set(routes)=={\'private\',\'head_only\'}:\n                a,ap=routes[\'private\'];b,bp=routes[\'head_only\']\n                if ap[\'stream_sha256\']!=bp[\'stream_sha256\']:raise RuntimeError(\'Unpaired BERT architecture controls\')\n                disagreements=((a.decision!=b.decision)|(a.adapter.fillna(\'DEFER\')!=b.adapter.fillna(\'DEFER\')))\n                pairs.append({\'seed\':seed,\'order\':order,\'allocation_disagreements\':int(disagreements.sum()),\n                    \'private_spawn_steps\':json.dumps(a.loc[a.decision==\'spawn\',\'step\'].tolist()),\n                    \'head_only_spawn_steps\':json.dumps(b.loc[b.decision==\'spawn\',\'step\'].tolist()),\n                    \'private_learning_updates\':int(a.train_executed.sum()),\n                    \'head_only_learning_updates\':int(b.train_executed.sum())})\n    report=[\'# BERT allocation transfer diagnostic\',\'\',f\'Complete trajectories {len(rows)//3}/20; \'\n        f\'complete private/head-only pairs {len(pairs)}/10. Partial attempts: {partial}.\',\'\',\n        \'This transfer check replaces the backbone, representations, tokenizer, pooler and classifier. \'\n        \'It does not isolate classifier design alone or compare against a tuned static BERT baseline. \'\n        \'All deployment rules and both allocation controls are retained.\',\'\']\n    if rows:\n        frame=pd.DataFrame(rows);frame.to_csv(\'results/day16_bert_deployment.csv\',index=False)\n        pd.DataFrame(pairs).to_csv(\'results/day16_bert_allocation_pairs.csv\',index=False)\n        differences=[]\n        for key,part in frame.groupby([\'architecture\',\'rule\']):\n            complete=part.groupby(\'seed\').filter(lambda p:len(p)==2 and set(p.order)=={\'canonical\',\'b_first\'})\n            differences.append(dict(zip([\'architecture\',\'rule\'],key))|interval(\n                complete.groupby(\'seed\').bert_minus_distilbert.mean()))\n        summary=pd.DataFrame(differences);summary.to_csv(\'results/day16_bert_paired_differences.csv\',index=False)\n        report+=[\'## Every allocation pair\',\'\',markdown_table(pd.DataFrame(pairs)),\'\',\n            \'## Descriptive cross-backbone accuracy differences\',\'\',markdown_table(summary),\'\',\n            \'## Every trajectory and prediction rule\',\'\',markdown_table(frame),\'\']\n    report+=[\'Intervals average both orders within each independent seed. The fixed development examples \'\n        \'have been repeatedly examined; this is development evidence. Scope is the BANKING label-group \'\n        \'stress test, the frozen training recipe and the declared memory budget. Neither allocation \'\n        \'equivalence nor disagreement alone establishes competitive utility or a general capacity principle.\']\n    Path(\'notes/day16_bert_allocation_results.md\').write_text(\'\\n\'.join(report)+\'\\n\')\n    print(\'DAY16_BERT_REPORT_SAVED\',len(rows)//3,len(pairs),\'pairs\',flush=True)\n\n\nif __name__==\'__main__\':main()\n', 'experiments/day15_16_research_worker.py': '"""Execute frozen transfer/causal diagnostics and push every preserved attempt."""\nfrom datetime import datetime,timezone\nimport fcntl\nimport hashlib\nimport json\nimport os\nfrom pathlib import Path\nimport subprocess\nimport sys\n\n\nROOT=Path(\'/workspace/mitosis-interference\')\nos.chdir(ROOT)\nENV=os.environ.copy()\nENV.update(OMP_NUM_THREADS=\'8\',TOKENIZERS_PARALLELISM=\'false\',GIT_TERMINAL_PROMPT=\'0\',GH_PROMPT_DISABLED=\'1\')\nENV[\'MITOSIS_MODEL_REVISION\']=json.loads(Path(\'notes/restart_20261006_preflight.json\').read_text())[\'backbone_revision\']\nBRANCH=\'day5-causal-audit\'\nLAUNCH_CUTOFF=datetime.fromisoformat(\'2026-10-07T03:00:00+00:00\')\nTRAINING_DEADLINE=\'2026-10-07T03:15:00+00:00\'\n\n\ndef now():return datetime.now(timezone.utc).isoformat()\n\n\ndef read(command):return subprocess.check_output(command,env=ENV,text=True,timeout=90).strip()\n\n\ndef command(arguments,log=None):\n    print(\'RUN\',\' \'.join(arguments),flush=True)\n    return subprocess.run(arguments,env=ENV,stdin=subprocess.DEVNULL,\n                          stdout=log,stderr=subprocess.STDOUT if log else None).returncode\n\n\ndef write(path,data):\n    p=Path(path);temporary=p.with_suffix(p.suffix+\'.tmp\')\n    temporary.write_text(json.dumps(data,indent=2)+\'\\n\');temporary.replace(p)\n\n\ndef preserve():\n    manifest={}\n    for path in sorted(Path(\'results\').rglob(\'*\')):\n        if path.is_file() and \'checkpoint\' in path.parts:\n            digest=hashlib.sha256()\n            with path.open(\'rb\') as stream:\n                for block in iter(lambda:stream.read(8*1024*1024),b\'\'):digest.update(block)\n            manifest[str(path)]={\'bytes\':path.stat().st_size,\'sha256\':digest.hexdigest()}\n    write(\'results/checkpoint_preservation_manifest.json\',manifest)\n    preservation=json.loads(Path(\'notes/preservation_status.json\').read_text())\n    preservation.update(checkpoint_files=len(manifest),checkpoint_bytes=sum(x[\'bytes\'] for x in manifest.values()),\n                        new_snapshot_push_pending=True,github_ref_verified=False,\n                        remote_checkpoints_sha256_verified=False)\n    write(\'notes/preservation_status.json\',preservation)\n    if command([\'git\',\'add\',\'-A\']):raise RuntimeError(\'Git staging failed\')\n    if read([\'git\',\'status\',\'--porcelain\']):\n        if command([\'git\',\'commit\',\'-m\',\'Preserve frozen architecture and weight-state audit progress\']):\n            raise RuntimeError(\'Git progress commit failed\')\n    if command([\'git\',\'push\',\'origin\',BRANCH]):raise RuntimeError(\'GitHub progress push failed; local state preserved\')\n    head=read([\'git\',\'rev-parse\',\'HEAD\'])\n    if read([\'git\',\'ls-remote\',\'origin\',\'refs/heads/\'+BRANCH]).split()[0]!=head:\n        raise RuntimeError(\'GitHub progress ref does not match\')\n    if read([\'git\',\'status\',\'--porcelain\']):raise RuntimeError(\'Unexpected uncommitted state\')\n    print(\'DIAGNOSTIC_PROGRESS_PUSHED\',head,flush=True)\n\n\nlock=open(\'/workspace/mitosis-restart-worker.lock\',\'a\')\nfcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)\nassert read([\'git\',\'branch\',\'--show-current\'])==BRANCH\nassert read([\'git\',\'remote\',\'get-url\',\'origin\'])==\'https://github.com/anitusiruk/mitosis-interference.git\'\nassert not read([\'git\',\'status\',\'--porcelain\'])\nassert read([\'gh\',\'api\',\'repos/anitusiruk/mitosis-interference\',\'--jq\',\'.permissions.push\'])==\'true\'\nrecords=[];failed=False\njobs=[]\nfor seed in range(2027,2032):\n    for order in [\'canonical\',\'b_first\']:\n        for architecture in [\'private\',\'head_only\']:\n            name=f\'day16_banking_{architecture}_seed{seed}_{order}_bert\'\n            jobs.append((name,\'experiments.day16_bert_allocation\',\n                         [\'--architecture\',architecture,\'--seed\',str(seed),\'--order\',order],16))\nfor seed in range(2027,2032):\n    for order in [\'canonical\',\'b_first\']:\n        for regime in [\'banking\',\'amazon\']:\n            name=f\'day15_{regime}_private_cau_seed{seed}_{order}_weight_moments\'\n            jobs.append((name,\'experiments.day15_weight_moment_recurrence\',\n                         [\'--regime\',regime,\'--seed\',str(seed),\'--order\',order],15))\nstatus=Path(\'notes/day15_16_execution_status.json\')\nif status.exists():\n    records=json.loads(status.read_text())[\'jobs\']\n    if any(r[\'status\']!=\'completed\' for r in records):\n        raise RuntimeError(\'Preserved incomplete/failed diagnostic attempt requires inspection\')\nfor name,module,args,study in jobs:\n    old=[r for r in records if r[\'name\']==name]\n    if old:\n        assert len(old)==1 and old[0][\'status\']==\'completed\'\n        assert json.loads(Path(\'results\',name,\'summary.json\').read_text())[\'status\']==\'completed\'\n        if study==15:assert json.loads(Path(\'results\',name,\'observer_verification.json\').read_text())[\'status\']==\'passed\'\n        continue\n    if datetime.now(timezone.utc)>=LAUNCH_CUTOFF:\n        print(\'DIAGNOSTIC_LAUNCH_CUTOFF\',now(),flush=True);break\n    output=Path(\'results\')/name\n    assert not output.exists(),\'Refusing to overwrite \'+str(output)\n    arguments=[sys.executable,\'-u\',\'-m\',module,*args,\'--output\',str(output),\'--deadline-utc\',TRAINING_DEADLINE]\n    row={\'name\':name,\'study\':study,\'status\':\'running\',\'started_utc\':now(),\'command\':arguments}\n    records.append(row);write(status,{\'jobs\':records,\'planned_jobs\':40,\'generated_utc\':now(),\'github_save_pending\':True})\n    with Path(\'logs\',name+\'.txt\').open(\'x\') as log:code=command(arguments,log)\n    row.update(returncode=code,finished_utc=now(),status=\'completed\' if code==0 else \'failed\')\n    write(status,{\'jobs\':records,\'planned_jobs\':40,\'generated_utc\':now(),\'github_save_pending\':True})\n    print(\'DIAGNOSTIC_JOB\',name,row[\'status\'],flush=True)\n    report=\'experiments.day16_bert_report\' if study==16 else \'experiments.day15_moment_report\'\n    report_log=Path(\'logs\',name+\'_report.txt\')\n    with report_log.open(\'x\') as log:report_code=command([sys.executable,\'-u\',\'-m\',report],log)\n    if report_code:row[\'report_failed\']=True\n    write(status,{\'jobs\':records,\'planned_jobs\':40,\'generated_utc\':now(),\'github_save_pending\':True})\n    with Path(\'logs\',name+\'_progress.txt\').open(\'x\') as log:\n        progress_code=command([sys.executable,\'-u\',\'-m\',\'experiments.day13_progress_report\'],log)\n    if progress_code:row[\'progress_report_failed\']=True\n    write(status,{\'jobs\':records,\'planned_jobs\':40,\'generated_utc\':now(),\'github_save_pending\':True})\n    preserve()\n    if code or report_code or progress_code:failed=True;break\npreserve()\nif command([sys.executable,\'-u\',\'-m\',\'experiments.finalize_github_save\']):\n    raise RuntimeError(\'Diagnostic remote checkpoint roundtrip failed\')\nreceipt=json.loads(Path(\'notes/github_save_verification.json\').read_text())\nassert receipt[\'all_current_lfs_sha256_verified\']\npreservation=json.loads(Path(\'notes/preservation_status.json\').read_text())\npreservation.update(github_push_returncode=0,github_ref_verified=True,new_snapshot_push_pending=False,\n    remote_checkpoints_sha256_verified=True,last_successful_github_snapshot_commit=receipt[\'preserved_snapshot_commit\'],\n    last_successful_github_save_verified_utc=receipt[\'verified_utc\'])\nwrite(\'notes/preservation_status.json\',preservation)\nwrite(status,{\'jobs\':records,\'planned_jobs\':40,\'generated_utc\':now(),\'github_save_pending\':False,\n              \'github_save_verified\':True,\'failed\':failed,\'complete\':len(records)==40 and not failed})\nif command([\'git\',\'add\',\'notes/preservation_status.json\',str(status)]):raise RuntimeError(\'Final Git stage failed\')\nif command([\'git\',\'commit\',\'-m\',\'Record verified GitHub checkpoint preservation for frozen diagnostics\']):\n    raise RuntimeError(\'Final Git commit failed\')\nif command([\'git\',\'push\',\'origin\',BRANCH]):raise RuntimeError(\'Final Git push failed\')\nhead=read([\'git\',\'rev-parse\',\'HEAD\'])\nassert read([\'git\',\'ls-remote\',\'origin\',\'refs/heads/\'+BRANCH]).split()[0]==head\nassert not read([\'git\',\'status\',\'--porcelain\'])\nprint(\'DIAGNOSTIC_QUEUE_AND_GITHUB_SAVE_COMPLETE\',head,\'JOBS\',len(records),\'FAILED\',failed,flush=True)\nif failed:raise RuntimeError(\'Research discrepancy preserved; inspect before continuing\')\n', 'experiments/day13_progress_report.py': '"""Regenerate a concise research handoff from verified saved outputs."""\nfrom datetime import datetime,timezone\nimport json\nfrom pathlib import Path\nimport pandas as pd\nfrom experiments.day5_report import markdown_table\n\ndef table(path,columns=None):\n    p=Path(path)\n    if not p.exists():return \'Pending; no saved completed-result table yet.\'\n    try:d=pd.read_csv(p)\n    except pd.errors.EmptyDataError:return \'Pending; no complete fresh-seed comparison groups yet.\'\n    if d.empty:return \'Pending; no complete comparison groups yet.\'\n    if columns is not None:d=d[columns]\n    return markdown_table(d)\n\ncounts=[]\nfor day,expected in [(5,6),(6,80),(7,24),(9,110),(8,44),(10,12),(12,11)]:\n    path=Path(f\'logs/day{day}_\'+(\'routing_status.json\' if day==9 else \'queue_status.json\'))\n    records=json.loads(path.read_text()) if path.exists() else []\n    counts.append({\'study\':str(day),\'completed\':sum(x[\'status\']==\'completed\' for x in records),\n                   \'planned\':expected,\'last_status\':records[-1][\'status\'] if records else \'not launched\'})\nfixed_router=Path(\'logs/day14_fixed_memory_routing_status.json\')\nif fixed_router.exists():\n    records=json.loads(fixed_router.read_text())\n    counts.append({\'study\':\'14 fixed-memory routing\',\'completed\':sum(x[\'status\']==\'completed\' for x in records),\n                   \'planned\':44,\'last_status\':records[-1][\'status\'] if records else \'not launched\'})\ndiagnostics=Path(\'notes/day15_16_execution_status.json\')\nif diagnostics.exists():\n    records=json.loads(diagnostics.read_text())[\'jobs\']\n    for study in [15,16]:\n        part=[x for x in records if x[\'study\']==study]\n        counts.append({\'study\':str(study),\'completed\':sum(x[\'status\']==\'completed\' for x in part),\n                       \'planned\':20,\'last_status\':part[-1][\'status\'] if part else \'not launched\'})\nhead=Path(\'logs/day5_head_only_queue_status.json\')\nif head.exists():counts.append({\'study\':\'5 head-only\',\'completed\':sum(r[\'status\']==\'completed\' for r in json.loads(head.read_text())),\n                               \'planned\':2,\'last_status\':json.loads(head.read_text())[-1][\'status\']})\nreport=[\'# Research progress and evidence handoff\',\'\',\n    \'Generated \'+datetime.now(timezone.utc).isoformat()+\'. This is a development report, not a submission-ready paper.\',\'\',\n    \'## Decision\',\'\',\n    \'Carry forward the mechanistic audit and the original private-package implementation as a reference. \'\n    \'The present results do not establish that the allocation policy identifies a need for new LoRA capacity, \'\n    \'or that it improves deployable accuracy across these regimes. The useful candidate contribution is a \'\n    \'controlled account of classifier resets, optimizer state, prospective learning gain, and inference routing. \'\n    \'Modern source-faithful comparators and stronger same-label learning regimes are still required.\',\'\',\n    \'## Verified study coverage\',\'\',markdown_table(pd.DataFrame(counts)),\'\',\n    \'Complete trajectories alone enter summaries. A queue record is an execution status; the independent \'\n    \'evidence audit also checks the saved trajectory summary, full step count and final metrics.\',\'\',\n    \'## Primary five-seed results\',\'\',\n    \'Seeds 2027–2031 each have canonical and B-first orders. Average both orders within a seed before \'\n    \'descriptive 95% Student-t intervals. Fixed development examples define the scope; windows and orders \'\n    \'are not independent replicates. All three fixed routing rules are reported. Macro accuracy averages \'\n    \'three concept-level accuracies; it is not BANKING per-class macro accuracy.\',\'\',\n    table(\'results/day6_seed_cluster_summary.csv\',[\'regime\',\'rule\',\'architecture\',\'policy\',\'seed_clusters\',\'mean\',\'ci_low\',\'ci_high\']),\'\',\n    table(\'results/day6_paired_differences.csv\'),\'\',\'\',\n    \'## Mechanism\',\'\',\n    \'On the original BANKING trajectory, fresh classifier reset with reused LoRA yielded substantially larger \'\n    \'held-out one-step loss gains than replacing LoRA under a fresh classifier. The factorial changes both \'\n    \'component weights and their corresponding AdamW moments, so it does not identify weights independently \'\n    \'of moments. About 87% of fresh-versus-best-reuse utility at both spawn steps was an initial predictor \'\n    \'gap, before the proposed update. Initial gap itself changes the whole package, not only the head.\',\'\',\n    \'The BANKING private and zero-LoRA head-only controllers made identical adapter/decision sequences \'\n    \'across all ten fresh-seed/order trajectories. LoRA training improved classifier performance despite \'\n    \'these identical structural decisions. Do not conflate prediction benefit with allocation necessity.\',\'\',\n    table(\'results/day13_head_allocation_comparison.csv\'),\'\',\'\',\n    \'The closed-loop pre-update ranking sensitivity preserves prospective AdamW retention guards. \'\n    \'Its original seed-2026 pilots made no allocation changes. This does not show that all lookahead \'\n    \'computation is unnecessary: prospective protected-memory checks remain. Later pilot seeds are shown below.\',\'\',\n    table(\'results/day10_initial_loss_comparison.csv\'),\'\',\'\',\n    \'## Third regime and deployment\',\'\',\n    \'MultiNLI uses only training data, with normalized-premise-grouped development holdout, genuine paired \'\n    \'tokenization and sharp/blurry transitions that preserve examples. Three seeds and two boundary variants \'\n    \'are descriptive transfer checks. The 64-token, 1440-example stress test produces low learning; allocation \'\n    \'often performs near balanced chance (one third). It is not a competitive NLI benchmark.\',\'\',\n    table(\'results/day7_multinli_comparison.csv\',[\'seed\',\'condition\',\'architecture\',\'policy\',\'rule\',\'macro_accuracy\',\'updates\',\'adapters\']),\'\',\'\',\n    \'A standard linear router was added after the initial routing failure, then frozen before its own outcomes. \'\n    \'It learns past adapter ownership from training reservoir texts without true task IDs or class labels. \'\n    \'Both hard routing and probability mixture are auxiliary development outcomes; their use is not a new \'\n    \'routing contribution or a reproduction of L2R/HESTIA. Checkpoint reload checks compare nine aggregate \'\n    \'sample counts and accuracies, not previously saved per-example prediction vectors.\',\'\',\n    table(\'results/day9_routing_paired_differences.csv\'),\'\',\'\',\n    \'## Resource sensitivities\',\'\',\n    \'The fixed-memory extension limits total stored training examples to 512 and preserves 64-example probes. \'\n    \'It also caps the pool at eight. The rank-96 single baseline was selected by parameter arithmetic near \'\n    \'three rank-8 private packages; it is not universally parameter matched to an uncapped growing pool. \'\n    \'Memory, head storage, optimizer state, active-update compute and inference compute remain separate resources. \'\n    \'Poor rank-96 performance under the shared fixed recipe does not establish superiority over a tuned \'\n    \'larger static baseline; baseline-specific tuning with pilot/confirmation separation remains necessary.\',\'\',\n    table(\'results/day8_memory_paired_differences.csv\'),\'\',\'\',\n    table(\'results/day12_capacity_paired_differences.csv\'),\'\',\'\',\n    \'## Fixed-memory learned routing and extended attribution\',\'\',\n    table(\'results/day14_memory_routing_paired_differences.csv\'),\'\',\'\',\n    \'The Day-15 observer independently crosses LoRA/head weights with LoRA/head AdamW state. \'\n    \'All mature batches and every cell are retained. Only verified bitwise paired trajectory/state \'\n    \'reproductions enter its causal summaries. The Day-16 BERT check tests transfer beyond the \'\n    \'DistilBERT classifier stack; multiple backbone components change together, so it does not \'\n    \'isolate classifier architecture causally. Both studies are development extensions, not untouched \'\n    \'test confirmations. Current novelty limits are in notes/novelty_audit_20261006.md.\',\'\',\n    table(\'results/day15_seed_intervals.csv\'),\'\',\'\',\n    table(\'results/day16_bert_allocation_pairs.csv\'),\'\',\'\',\n    \'## Methodological checks and limits\',\'\',\n    \'The shared-head, component, head-only, stream-order, MultiNLI data, fixed-memory and scoring integrity \'\n    \'tests passed in the live environment. Original BANKING/Amazon Day-4 routing was reproduced with zero \'\n    \'disagreements. Complete shadow transactions were checked against exact parameter, optimizer, RNG \'\n    \'and reservoir restoration in their declared test scope. Legacy private probes clear stale gradients; \'\n    \'the next real training update clears them anyway. Do not claim that all legacy probes restore gradient flags.\',\'\',\n    \'The frozen retention rule is harm_LCB <= 0 with z=1.96. It permits small positive mean harm on some \'\n    \'Amazon probes and is not a 95% no-forgetting guarantee or an anytime-valid repeated-test procedure. \'\n    \'No threshold has been retuned to fix that interpretation. Day-2 strict robustness failure and \'\n    \'Day-4 v0 starvation remain recorded failures.\',\'\',\n    \'Official tests were not used in these live experiments. Earlier BANKING exploratory work did use \'\n    \'official test data before the clean development protocol; disclose this history in the paper. \'\n    \'Do not describe BANKING official test as never observed. MultiNLI official validation remains unused.\',\'\',\n    \'The normalized-text and token-truncation audit is an additional offline diagnostic of the existing \'\n    \'split. If it finds overlap, retain these original results and declare a grouped split as a new protocol \'\n    \'rather than silently filtering an outcome-selected subset.\',\'\',\n    table(\'results/day13_split_audit.csv\',[\'regime\',\'seed\',\'normalized_train_dev_unique_overlap\',\n          \'truncated_token_train_dev_unique_overlap\',\'training_fraction_over_64_tokens\',\'development_fraction_over_64_tokens\']),\'\',\'\',\n    \'## Reproduction and preservation\',\'\',\n    \'The working branch is day5-causal-audit; master remains the restored Day-4 reference. All live trajectories \'\n    \'record source hashes, package versions, stream hashes and saved final learner state. The older model-revision \'\n    \'field is null; exact historical backbone identity was not recorded. The restart records an explicit \'\n    \'Hugging Face commit and backbone file hashes, and verifies saved aggregate predictions and losses before \'\n    \'new outcomes. This numerical reload check does not prove historical byte identity. \'\n    \'The saved GitHub snapshot and all 738 checkpoint files were successfully restored on the new pod; \'\n    \'notes/github_save_verification.json records the earlier authenticated save. Source-only archives and \'\n    \'Git bundles omit LFS tensor content. New work requires its own successful GitHub save before pod shutdown.\',\'\',\n    \'To recover committed history from the final bundle:\',\'\',\n    \'```bash\\ngit clone mitosis-research-final.bundle mitosis-interference\\ncd mitosis-interference\\n\'\n    \'git checkout day5-causal-audit\\nexport PYTHONPATH="$PWD"\\n```\',\'\',\n    \'Regenerate analyses with the corresponding experiments.day5_report, day6_diagnostic_report, \'\n    \'day7_multinli_report, day9_routing_report, day8_fixed_memory_report, day10_mechanism_report, \'\n    \'day12_capacity_report, day13_evidence_audit and day13_progress_report modules. Scientific plots are \'\n    \'generated by experiments.day13_evidence_figures. Do not rerun existing output directories.\',\'\',\n    \'## Remaining research schedule\',\'\',\n    \'1. Complete the frozen controls and independently inspect data/implementation audits.\\n\'\n    \'2. Reproduce the closest CABLE signal and at least one modern structural method from verified author code; \'\n    \'keep task-boundary-informed conditions separate.\\n\'\n    \'3. Run longer same-label adaptation regimes with useful fixed-baseline learning; freeze router and resource \'\n    \'protocol before new confirmation seeds.\\n\'\n    \'4. Separate head-weight reset from moment reset and test an intervention whose structural interpretation \'\n    \'matches its claimed capacity resource.\\n\'\n    \'5. Only after complete-method freeze, run held-out evaluation with the earlier BANKING exposure disclosed, \'\n    \'dedicated resource measurement and external baselines.\\n\'\n    \'6. Write a claim-supported paper and author verification record. The fifteen-day plan is a planning budget, \'\n    \'not a reason to submit unsupported findings.\',\'\',\n    \'## Day-5 tracker\',\'\',\n    \'Causal audit: complete. Core LoRA-specific allocation claim: not established. Seed/order diagnosis: \'\n    \'complete. Third-regime stress test: complete but low learning. Further controls: coverage table above. \'\n    \'Modern baselines, complete-method confirmation and submission readiness: pending.\']\nPath(\'notes/research_progress.md\').write_text(\'\\n\'.join(report)+\'\\n\')\nprint(\'PROGRESS_REPORT_SAVED\',flush=True)\n', 'notes/day15_weight_moment_spec.md': "# Separate weight and optimizer-state attribution\n\nThis extension was designed after the Day-5/6 classifier-only allocation equivalence\nand Day-10 initial-loss-ranking results were observed. It is a development-stage\ncausal diagnostic, not untouched confirmation of a newly discovered hypothesis.\nIts four-factor intervention and analysis are frozen before its research outcomes.\nTiny implementation-integrity checks are not research outcomes.\n\n## Question and estimand\n\nDoes the measured one-step fresh-package advantage reflect classifier weight\nreset, the optimizer-state reset accompanying it, LoRA reset, or interactions\namong them? The original component factorial changed weights and corresponding\nAdamW states together. Its results cannot distinguish those mechanisms.\n\nAt each mature incoming batch of the existing private CAU-v1 fixed-512 trajectory,\ncross all four binary factors: inherited/reset LoRA weights, inherited/reset\nclassifier-stack weights, inherited/empty LoRA AdamW state, and inherited/empty\nclassifier-stack AdamW state. Run all 16 cells in both complementary even/odd\nsupport/query folds. Use every incoming example exactly once as a query in every\ncell. Observe every mature batch, including batches without expansion and with\nnegative or zero measured contrasts; do not select windows by effect size.\n\n“Reset head” means PEFT's original classifier/pre-classifier initializer, which is\ncopied from the original frozen modules. It is not an independent new random draw.\nLoRA initialization and support dropout randomness are matched across cells.\nInherited optimizer state includes AdamW step, first moment and second moment,\nnot moments alone. Attaching inherited state to reset weights is an artificial\ncausal intervention; it need not be a useful deployment recipe. Transported states\nare matched by normalized parameter name and exact shape. The AdamW parameter\ngroup, learning rate, clipping at 1.0 and update count remain unchanged.\n\nThe reference predictor is the inherited-weight source before the update.\nFor every cell, record initial query loss, post-update query loss, local improvement,\nper-example query losses, component update norm, and hashes of supplied weights\nand optimizer state. For source r and candidate a, report the exact identity\n\nU(a) = L(r before) - L(a after)\n     = [L(r before) - L(a before)] + [L(a before) - L(a after)].\n\nThis algebra is elementary and is not claimed as a novel theorem. Initial predictor\nquality is legitimate evidence for an immediate post-update prediction objective;\nit is insufficient by itself to identify a need for additional LoRA capacity or\nenhanced trainability. A reset need not imply recovered plasticity on future data.\n\nAlso decompose each already-computed query cross entropy into the loss of\nprobability mass assigned to its label group and the conditional classification\nloss inside that group: CE(y over full output space) = -log P(group|x) +\nCE(y conditioned on group). BANKING uses its three predeclared 11-label groups;\nAmazon uses the full shared two-label group, whose mass loss is exactly zero.\nGroup identities are evaluator-only metadata used to interpret already computed\nlogits. They never enter allocation, gradients, training or deployed routing.\nSave both components before/after every cell and report all factor effects on\nthem. The identity is elementary, not a new theorem. Decomposition agreement\nuses absolute 1e-5 tolerance for float32 reductions. Do not interpret conditional\ngroup accuracy as a label-free deployed result or an oracle advantage.\n\nThis label-mass analysis was added before any Day-15/16 research outcomes or\nGitHub preregistration, after the first CPU implementation gates. The pending\ninstaller was paused for the amendment; the original frozen GPU queue continued.\n\n## Frozen coverage and comparisons\n\nUse BANKING and Amazon, the two existing orders, and seeds 2027–2031: 20 observer\ntrajectories, each paired to its saved complete private CAU fixed-512 reference.\nDo not tune on these measurements. Historical aggregate backbone reload equality\nis not byte-identity proof. Every observer must additionally reproduce its complete\nreference action/memory trajectory, training losses within absolute 1e-6, and final\nlearner state and adapter tensors bitwise. Independently check full state restoration\naround every batch's observer. A failed verification halts the queue, preserves the\nattempt and excludes its contrasts from causal aggregation until the discrepancy\nis resolved transparently. Never quietly relabel a failed audit as a replicate.\n\nThe analysis source is the actual active package at that batch, not a retrospectively\nchosen best adapter. These contrasts therefore attribute the active-package probe,\nnot every best-feasible-reuse controller comparison. This distinction must remain\nin the paper. The observer does not participate in allocation or training.\n\nReport simple conditional effects of each factor at all eight settings of the other\nthree factors; also report equal-weight marginal effects and two-factor interactions.\nUse post-update query-loss decrease as the effect orientation (positive is better).\nSplit every post-update contrast into its initial-loss contrast and local-improvement\ncontrast. Verify this decomposition numerically at every paired batch/cell/fold.\nWeight folds by query count; average mature batches within each trajectory; average\nthe two orders within a seed; then give all five seed values and descriptive Student\n95% intervals. The independent unit is training seed, not batch, fold, or example.\nReport every conditional contrast and both regimes. Do not select a favorable cell\nor sign. Per-batch displays are descriptive. Ratios are omitted when denominators\nare near zero; do not report unbounded “fraction explained” as a causal share.\n\nBANKING's disjoint label-group stream and Amazon's same-label domain stream supply\ndifferent conditions, not two interchangeable replications. Existing MultiNLI\nresults are near chance and cannot establish a competitive natural-language\nadaptation claim. Broader backbones and stronger natural same-label training remain\nnecessary to support claims beyond this allocator and these small stress tests.\n\n## Gates and preservation\n\nBefore research execution, pass CPU and CUDA tiny real PEFT/AdamW tests for all 16\ncells, exact live-state restoration, matched fresh initialization, independent state\ntransport, initial-prediction invariance to moments, equality with original coupled\ncells, equality with a real inherited update, odd-batch coverage, and cell-order\ninvariance. Save passing logs and the earlier implementation failure/repair record.\n\nCommit this spec and implementation to the existing day5-causal-audit branch before\nlaunch. Never overwrite an existing result folder. Queue in seed, order, regime\norder (BANKING then Amazon within each seed/order), independent of observed effects.\nAn administrative launch cutoff or interrupted run does not change hypotheses;\nreport incomplete coverage explicitly and resume only previously unlaunched jobs.\nPreserve every raw attempt, complete checkpoints, code, provenance, and summaries\nin anitusiruk/mitosis-interference only. Official test sets are not evaluated here.\n", 'notes/day16_bert_allocation_spec.md': "# Classifier architecture transfer diagnostic\n\nFreeze before BERT research outcomes. The DistilBERT allocation findings and the\nnovelty audit motivated this extension. It is a development-stage transfer check,\nnot a new independent test-set confirmation or a competitive benchmark.\n\nQuestion: Does the observed equivalence between full-package and classifier-only\nallocation survive replacing DistilBERT's trainable pre-classifier/classifier stack\nwith BERT's single linear classifier on a frozen pooler? A different result is a\nvaluable boundary of the finding; it must not be suppressed or “repaired” by tuning.\n\nUse google-bert/bert-base-uncased, resolving and hashing one immutable revision\nbefore execution. Store config, tokenizer and backbone SHA256 manifest; do not\nsubstitute a later model snapshot. Use rank-8/alpha-16 LoRA on every query/value\nattention projection, zero LoRA dropout, the original clipped AdamW lr=0.0002\ntraining recipe, 64-token context, 512-total-item reservoirs, 64-item probes,\nmaximum eight packages, and unchanged CAU-v1 allocation/protection semantics.\nPretrained backbone and pooler remain frozen. The head-only control keeps LoRA\noutputs identically zero and optimizes only the private linear classifier.\n\nRun BANKING seeds 2027–2031, both canonical/B-first orders, private and head-only:\n20 trajectories, exact stream SHA matches to corresponding Day-8 references.\nQueue seed, order, private then head-only. No task identities are supplied to\nallocation or prediction. Evaluation-only concept metadata remain in the data\nbuilder and metrics. Official test sets are not evaluated. Dataset/pretraining\nexposure limits already recorded for the project still apply.\n\nPrimary outcome: complete decision/selected-package disagreement count between\nprivate and head-only within each BERT seed/order. Also retain all spawn steps,\nlearning updates, package counts, initial/predicted utilities and all three frozen\nlabel-free deployment rules. Compare these descriptive allocation outcomes with\nDistilBERT on the same streams. A changed training/backbone recipe cannot be a\ncausal attribution solely to classifier design: backbone depth, representations,\ntokenization, frozen pooler and classifier all differ. This is cross-architecture\ntransfer evidence, not a one-factor classifier experiment.\n\nAverage two orders within seed for descriptive accuracy differences and show all\nfive seed values. Five seeds and fixed repeatedly inspected development examples\ndo not support broad population inference. No best routing rule or favorable seed\nis selected. There is no tuned fixed-single baseline in this extension, so no claim\nthat BERT allocation outperforms a fair static alternative is permitted. Learning\ncurves are diagnostics; if learning is weak, say so and plan separate fair tuning.\n\nBefore execution, pass real tiny BERT/PEFT tests for private classifier detection,\nzero-output head-only LoRA, frozen pooler, exact transactional crossfit restoration,\nbounded-memory lifecycle, and cloned inherited update equivalence. Preserve all\nfailed attempts, halt on nonfinite losses or budget/data mismatch, refuse to\noverwrite outputs, and save complete checkpoints and raw logs to the existing\nmitosis-interference branch. Run one GPU experiment at a time; wall time is\ndescriptive and is not a dedicated hardware benchmark.\n", 'notes/novelty_audit_20261006.md': "# Updated novelty assessment and contribution boundary\n\nChecked 2026-10-06. This is a focused primary-source audit, not an exhaustive\npriority search or a numerical probability of acceptance. Current readiness is\nlow: a plausible methodological-audit contribution remains, but the evidence\ndoes not yet justify submission.\n\n| Primary work | What it already establishes | Boundary for this project |\n| --- | --- | --- |\n| Wang et al., [Predicting Plasticity in Deep Continual Learning](https://arxiv.org/html/2605.09044v1), May 2026 | Defines trainability through normalized future optimization gain; explains why absolute gains across different initial losses can mislead; supplies theoretical counterexamples to structural diagnostics and an optimization-readiness measure. | Neither prospective gain as a diagnostic nor the distinction between initial quality and improvement is new. Our candidate finding is about actual reuse/expansion decisions in classifier-bearing packages under exact inherited AdamW state. No new trainability theorem is claimed. |\n| Lyle et al., [Disentangling the Causes of Plasticity Loss](https://proceedings.mlr.press/v274/lyle25a.html), CoLLAs 2025 | Studies multiple mechanisms and combined interventions for preserving plasticity. | Multi-factor causal diagnosis of plasticity is established. A weight/state factorial needs an informative allocation finding; the factorial alone is insufficient novelty. |\n| Hernandez-Garcia et al., [Reinitializing weights vs units](https://arxiv.org/html/2508.00212v1), 2025 | Compares selective weight reinitialization with unit reinitialization for maintaining plasticity. | Resetting weights or discovering a reset benefit is not a new contribution. Our one-step package result is not a proof of recovered future plasticity. |\n| Julian et al., [CABLE](https://www.nature.com/articles/s44387-025-00028-4.pdf), npj AI 2025 | Eq.10 multiplies post/pre incoming and remembered loss ratios after an SGD lookahead; a reinforcement-learning policy assigns classes to adapters. | Evaluating actual update consequences for allocation is established. Our additive common-reference score and batch-level decision are specific design choices, not priority over CABLE. An equation-level signal study is distinct from reproducing its full PPO system. |\n| Wei et al., [Online-LoRA](https://arxiv.org/html/2411.05663v1), 2024/2025 | Uses loss plateaus to expand LoRA, freezes/merges prior updates, and regularizes online parameter importance. | Task-free loss-triggered LoRA expansion is established. Its merged-backbone semantics differ from a selectable private-head package pool. No direct superiority claim follows without matched experiments. |\n| Wang et al., [SEMA](https://openaccess.thecvf.com/content/CVPR2025/papers/Wang_Self-Expansion_of_Pre-trained_Models_with_Mixture_of_Adapters_for_Continual_CVPR_2025_paper.pdf), CVPR 2025 | Uses representation descriptors for expansion and a learned adapter-mixture router. | Dynamic reuse/expansion and learned routing are established. Our linear ownership gate is an ordinary auxiliary control. |\n| Yildirim et al., [Pruned Adaptation Modules](https://arxiv.org/html/2603.21170v1), March 2026 | Argues for rigorous lightweight baselines and introduces sparse task-specific ResNet modules for vision class-incremental learning. | Weak fixed-capacity controls cannot support broad resource-efficiency claims. Author vision numbers are not comparable with our short text streams. |\n\n## Defensible question\n\nWhen an allocator evaluates a fresh classifier-and-LoRA package, what exactly\ndoes favorable prospective utility establish? The original predictor can lose\nmass on a newly arriving label group, while an initializer restores that mass\nbefore any update. A useful audit must identify this mechanism, distinguish\nclassifier weights from optimizer state, show its operational effect on actual\ndecisions, and delimit conditions where it disappears. It must also show that\nLoRA can improve prediction even when the allocation sequence is unchanged.\n\nInitial quality is a legitimate part of an immediate post-update prediction\nobjective. Calling it a bug or confound requires stating the stronger target\ninterpretation (need for more representation capacity or improved trainability).\nThe algebraic utility decomposition is elementary. Our study concerns CAU-v1;\nit does not by itself establish a defect in any named published allocator.\n\nThe novelty claim should remain provisional until separate weight/state results,\na second classifier architecture, meaningful same-label learning, and a relevant\nsource-faithful signal/method comparison establish a useful scope. If these\ncontrols show a narrow construction-specific effect, narrow the paper further\nor change direction; do not manufacture a new method claim from that effect.\n\n## Source-code audit caution\n\nRead-only inspection of jjul482/CABLE at the GitHub API-reported commit\n`c72b9cfeb345c8d517f1266ceb2b0ebf8a02430e` found an SGD virtual parameter\nupdate and Fisher-weighted squared-change normalization in\n`backbone/cable.py:compute_forgetting_score_adapters`. This inspected helper is\nnot Eq.10's direct loss-ratio expression. The top-level reinforcement module\nmust be traced before attributing full method semantics to that helper or\nclaiming a faithful reproduction. Preserve exact source hashes and distinguish\npublished equations, current author implementation, and any text adaptation.\nDo not quietly replace the paper's signal with a convenient approximation.\n\n## TMLR assessment\n\n[TMLR's acceptance criteria](https://jmlr.org/tmlr/acceptance-criteria.html)\nemphasize substantiated claims and findings of interest; state-of-the-art results\nare not required. Its [editorial policies](https://jmlr.org/tmlr/editorial-policies.html)\npermit modest contributions but require correct attribution of prior work.\nThe current route is an empirical methodological audit with clear limits. It is\nplausible, not established as sufficiently novel or ready, and no acceptance\nguarantee or calibrated numerical probability is available.\n", 'notes/day15_16_implementation_checks.md': "# Implementation checks before research outcomes\n\nThe four-factor audit's first CPU gate failed the equality check against the\noriginal coupled fresh-head cell. The original code computed mean cross entropy\ndirectly, while the new audit averaged separately computed per-example losses.\nThese mathematically equivalent reductions can differ at float32 precision.\nThe audit now computes its aggregate loss using the original reduction and also\nsaves per-example losses. The repaired CPU gate passed all 16 restoration checks,\ninitializer/state transport checks, real-update equality, odd-batch coverage and\ncell-order invariance. The failed and passing logs are retained.\n\nThe BERT gate's first attempt called the shared-head pool's `intervention` API on\nthe private pool, whose API is `shadow_reuse`. The test call was corrected; the\nlearner and allocation implementation did not change. Preserve both attempts.\n\nThe report is tested on synthetic known main effects and a known two-factor\ninteraction, with unequal fold sizes and five paired seed clusters. A single\nunpaired order must not contribute a seed interval. Synthetic data are temporary\ntest fixtures and never enter the research result tables.\n\nResearch launch additionally requires passing CUDA gates and an explicit BERT\nbackbone revision/file-hash manifest. Passing tiny tests does not prove the full\nscientific methodology. The Day-15 observer must reproduce the paired final\nlearner state and adapter tensors bitwise on the full real stream; discrepancies\nhalt execution and remain in the repository.\n"}
from pathlib import Path
