for old,new in [('cpu_integrity.log','day15_cpu_integrity_initial_failed.txt'),('cpu_integrity_v2.log','day15_cpu_integrity_repaired_stage.txt'),('additional_cpu_integrity.log','day16_cpu_integrity_initial_failed.txt'),('additional_cpu_integrity_v2.log','day16_cpu_integrity_repaired_stage.txt'),('bert_prefetch.log','day16_bert_prefetch.txt')]:
 source=stage/old;destination=root/'logs'/new
