checks=[('experiments.day15_moment_integrity',['--device','cpu'],'day15_cpu_integrity_final.txt'),('experiments.day15_moment_integrity',['--device','cuda'],'day15_cuda_integrity.txt'),('experiments.day16_bert_integrity',['--device','cpu'],'day16_cpu_integrity_final.txt'),('experiments.day16_bert_integrity',['--device','cuda'],'day16_cuda_integrity.txt'),('experiments.day15_report_integrity',[],'day15_analytic_report_integrity.txt')]
